xql_query:
// ============================================================
// Rule: MS_User Added to Monitored Group
// Vendor: Windows
// Objective:
// Detect activity associated with MS_User Added to Monitored Group.
// Severity: SEV_040_HIGH
// Category: PRIVILEGE_ESCALATION
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0004 - Privilege Escalation
// Technique: T1098 - Account Manipulation

preset = xdr_event_log
| filter action_evtlog_event_id in (4728, 4756)
| alter
    timestamp = _time,
    actor = actor_effective_username,
    TargetUserName = ACTION_EVTLOG_DATA_FIELDS -> TargetUserName,
    MemberSid = action_evtlog_data_fields -> MemberSid,
    MemberName = action_evtlog_data_fields -> MemberName,
    SubjectUserName = action_evtlog_data_fields -> SubjectUserName

| join conflict_strategy =both type = left (dataset=pan_dss_raw | fields display_name as target_user,sid) as whitelist whitelist.sid = MemberSid

| join conflict_strategy =both type = left (dataset=pan_dss_raw | fields display_name as executor, sam_account_name) as whitelist whitelist.sam_account_name  = SubjectUserName 

| fields action_evtlog_event_id, sam_account_name, target_user, executor, timestamp, agent_hostname, agent_ip_addresses, TargetUserName, MemberSid, SubjectUserName,MemberName
| join conflict_strategy =both type = left (dataset=monitored_groups | fields group) as whitelist whitelist.group = TargetUserName
| filter group != null
| filter (executor not contains """<IDENTITY_PROVISIONING_ACCOUNT>""" and TargetUserName not contains """VPN""")
